        if (content === contentScriptOld) return false

        const newStart = content.toLowerCase().indexOf('<script') 
        const oldStart = contentScriptOld.toLowerCase().indexOf('<script')
        if (newStart === -1 && oldStart === -1) return false

        const newEnd = content.toLowerCase().lastIndexOf('script>')
        const oldEnd = contentScriptOld.toLowerCase().lastIndexOf('script>')

        let newSubString = content.substring(newStart, newEnd)
        let oldSubString = contentScriptOld.substring(oldStart, oldEnd)

